/** Local socket/UI regression only. This is not the pending real-service acceptance test. */
@RunWith(AndroidJUnit4.class)
public final class RhSyncWireDeviceTest {
    private final RhSyncFlowDeviceTest d=new RhSyncFlowDeviceTest();private File output;private boolean passed;
    private static void preferences(SharedPreferences p,Map<String,?> values){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> x:values.entrySet()){Object v=x.getValue();if(v instanceof Boolean)e.putBoolean(x.getKey(),(Boolean)v);else if(v instanceof Long)e.putLong(x.getKey(),(Long)v);else if(v instanceof Integer)e.putInt(x.getKey(),(Integer)v);else if(v instanceof Float)e.putFloat(x.getKey(),(Float)v);else if(v instanceof String)e.putString(x.getKey(),(String)v);else if(v instanceof Set){Set<String> copy=new HashSet<>();for(Object item:(Set<?>)v)copy.add((String)item);e.putStringSet(x.getKey(),copy);}else throw new AssertionError("Unsupported preference type");}assertTrue(e.commit());}
    private static void bytes(File file,byte[] data)throws Exception{android.util.AtomicFile atomic=new android.util.AtomicFile(file);if(data==null){atomic.delete();return;}FileOutputStream out=atomic.startWrite();try{out.write(data);atomic.finishWrite(out);}catch(Exception error){atomic.failWrite(out);throw error;}}
    final class Snapshot implements AutoCloseable {
        final Context c=d.instrument.getTargetContext();final File shared=new File(c.getFilesDir(),"rhremote-shared.json"),account=new File(c.getFilesDir(),"webdav-local.json"),backups=new File(c.getFilesDir(),"sync-backups"),scratch;
        final byte[] originalShared=Files.readAllBytes(shared.toPath()),originalAccount=account.isFile()?Files.readAllBytes(account.toPath()):null;
        final SharedPreferences global=c.getSharedPreferences("rhremote.global",0),journal=c.getSharedPreferences("rhremote.sync.operations",0);final Map<String,?> oldGlobal=new HashMap<>(global.getAll()),oldJournal=new HashMap<>(journal.getAll());final boolean hadJournal=new File(c.getApplicationInfo().dataDir,"shared_prefs/rhremote.sync.operations.xml").isFile(),hadBackups=backups.exists();
        Snapshot(String run)throws Exception{scratch=new File(c.getFilesDir(),"ui-test-backups/"+run);assertFalse(scratch.exists());assertTrue(scratch.mkdirs());if(hadBackups)Files.move(backups.toPath(),new File(scratch,"original-backups").toPath());}
        public void close()throws Exception{
            if(d.activity!=null){long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(!d.activity.isDestroyed()){assertTrue("Owned Activity cleanup",System.nanoTime()<end);Thread.sleep(20);}}
            if(backups.exists())Files.move(backups.toPath(),new File(scratch,"test-backups").toPath());if(hadBackups)Files.move(new File(scratch,"original-backups").toPath(),backups.toPath());bytes(shared,originalShared);bytes(account,originalAccount);preferences(global,oldGlobal);preferences(journal,oldJournal);assertEquals(oldGlobal,global.getAll());assertEquals(oldJournal,journal.getAll());if(!hadJournal)assertTrue(c.deleteSharedPreferences("rhremote.sync.operations"));assertArrayEquals(originalShared,Files.readAllBytes(shared.toPath()));if(originalAccount!=null)assertArrayEquals(originalAccount,Files.readAllBytes(account.toPath()));else assertFalse(account.exists());RhShared.write(new File(output,"restored.json"),RhActions.obj("passed",passed,"sharedBytesRestored",true,"accountBytesRestored",true,"preferencesRestored",true,"originalBackupsRestored",true));
        }
    }
    private String text(View view){if(view.getVisibility()!=View.VISIBLE)return "";StringBuilder out=new StringBuilder();if(view instanceof TextView&&!(view instanceof EditText))out.append(((TextView)view).getText()).append('\n');if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)out.append(text(((ViewGroup)view).getChildAt(i)));return out.toString();}
    private String text(){String[] value={""};d.instrument.runOnMainSync(()->value[0]=text(d.activity.getWindow().getDecorView()));return value[0];}
    private void capture(String name)throws Exception{Bitmap[] image={null};d.instrument.runOnMainSync(()->{View decor=d.activity.getWindow().getDecorView();image[0]=Bitmap.createBitmap(decor.getWidth(),decor.getHeight(),Bitmap.Config.ARGB_8888);decor.draw(new Canvas(image[0]));});try(OutputStream out=new FileOutputStream(new File(output,name+".png"))){assertTrue(image[0].compress(Bitmap.CompressFormat.PNG,100,out));}finally{image[0].recycle();}}
    private <T extends View> T control(View root,Class<T> type){if(root.getVisibility()!=View.VISIBLE)return null;if(type.isInstance(root))return type.cast(root);if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){T found=control(((ViewGroup)root).getChildAt(i),type);if(found!=null)return found;}return null;}
    private void visible(View view){android.graphics.Rect bounds=new android.graphics.Rect(0,0,view.getWidth(),view.getHeight());view.requestRectangleOnScreen(bounds,true);}
    private void interval(int minutes){
        d.instrument.runOnMainSync(()->{Spinner spinner=control(d.activity.findViewById(android.R.id.content),Spinner.class);assertNotNull("Sync interval control",spinner);assertTrue(spinner.isEnabled());visible(spinner);spinner.setSelection(Arrays.asList(5,15,30,60).indexOf(minutes));});d.instrument.waitForIdleSync();assertEquals(minutes,d.state().optJSONObject("syncDraft").optInt("intervalMinutes"));
    }
    private void automatic(boolean enabled){
        d.instrument.runOnMainSync(()->{CheckBox box=control(d.activity.findViewById(android.R.id.content),CheckBox.class);assertNotNull("Automatic sync control",box);assertTrue(box.isEnabled());visible(box);if(box.isChecked()!=enabled)box.performClick();assertEquals(enabled,box.isChecked());});d.instrument.waitForIdleSync();assertEquals(enabled,d.state().optJSONObject("syncDraft").optBoolean("automatic"));
    }
    private void keepOwnedActivityAwake(){d.instrument.runOnMainSync(()->d.activity.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON));}
    private void formTop(){d.instrument.runOnMainSync(()->{ScrollView scroll=control(d.activity.findViewById(android.R.id.content),ScrollView.class);assertNotNull(scroll);scroll.scrollTo(0,0);});d.instrument.waitForIdleSync();}
    private void progress(String phase,long baseline,long began,RhSyncFlowDeviceTest.Fixture fixture)throws Exception{RhShared.write(new File(output,"progress.json"),RhActions.obj("phase",phase,"wallElapsedMs",System.currentTimeMillis()-baseline,"monotonicElapsedMs",TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-began),"getCount",fixture.gets.get(),"putCount",fixture.puts.get(),"sync",d.state().getJSONObject("sync"),"realService",false));}
    private void disabledEditors(View view){if(view.getVisibility()!=View.VISIBLE)return;if(view instanceof EditText||view instanceof CheckBox||view instanceof Spinner)assertFalse("Editable control during sync: "+view.getClass().getSimpleName(),view.isEnabled());if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)disabledEditors(((ViewGroup)view).getChildAt(i));}
    @Test public void actualFiveMinuteSchedulerUsesSavedIntervalAndSurvivesPageRecreation()throws Exception{
        assertTrue("Owned emulator required",android.os.Build.HARDWARE.equals("ranchu")||android.os.Build.HARDWARE.equals("goldfish"));String run=InstrumentationRegistry.getArguments().getString("wireRun","");assertTrue(run.matches("wire-auto-[a-z0-9-]{1,55}"));Context context=d.instrument.getTargetContext();output=new File(context.getExternalFilesDir("ui-evidence"),run);assertFalse(output.exists());assertTrue(output.mkdirs());
        try(Snapshot snapshot=new Snapshot(run);RhSyncFlowDeviceTest.Fixture fixture=new RhSyncFlowDeviceTest.Fixture();RhSyncFlowDeviceTest.Saved saved=d.new Saved()){
            try{
                RhShared.theme(context,false);saved.launch();keepOwnedActivityAwake();d.configure(fixture);d.click("立即同步");d.idle();long baseline=d.state().getJSONObject("sync").getLong("lastSyncMs"),began=System.nanoTime();assertEquals(1,fixture.puts.get());
                JSONArray choices=new JSONArray();for(int minutes:new int[]{5,15,30,60,5}){int previousInterval=new RhSync(context).state().getInt("intervalMinutes");interval(minutes);assertEquals("Selection alone must not save",previousInterval,new RhSync(context).state().getInt("intervalMinutes"));if(choices.length()==0){formTop();capture("interval-draft");}d.click("保存");JSONObject persisted=new RhSync(context).state();assertEquals(minutes,persisted.getInt("intervalMinutes"));assertFalse(persisted.getBoolean("automatic"));assertEquals(baseline,persisted.getLong("lastSyncMs"));choices.put(minutes);}
                automatic(true);assertFalse(new RhSync(context).state().getBoolean("automatic"));assertTrue(d.state().getBoolean("syncDirty"));d.click("保存");assertTrue(new RhSync(context).state().getBoolean("automatic"));assertEquals(5,new RhSync(context).state().getInt("intervalMinutes"));capture("automatic-saved");fixture.gate=true;
                boolean navigated=false,recreated=false;long reportAt=0;while(!d.state().getBoolean("syncBusy")){
                    long elapsed=System.currentTimeMillis()-baseline;assertTrue("No automatic request within one full interval plus scheduler allowance",elapsed<350000);assertEquals("Unexpected PUT before timer",1,fixture.puts.get());
                    if(elapsed>=30000&&!navigated){d.click("返回设备");assertEquals("devices",d.state().getString("page"));d.click("设置");d.click("配置同步");assertFalse(d.state().getBoolean("syncDirty"));assertTrue(d.state().getJSONObject("sync").getBoolean("automatic"));navigated=true;capture("returned-before-due");}
                    if(elapsed>=90000&&!recreated){d.recreate();keepOwnedActivityAwake();assertEquals("sync",d.state().getString("settingsTab"));assertEquals(baseline,d.state().getJSONObject("sync").getLong("lastSyncMs"));recreated=true;capture("recreated-before-due");}
                    if(elapsed>=reportAt){progress("waiting-for-actual-timer",baseline,began,fixture);reportAt=elapsed+10000;}Thread.sleep(100);
                }
                long dueWall=System.currentTimeMillis()-baseline,dueMonotonic=TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-began);assertTrue("Timer fired early",dueWall>=300000);assertTrue("Real monotonic wait was bypassed",dueMonotonic>=299000);assertTrue(navigated&&recreated);assertEquals(baseline,d.state().getJSONObject("sync").getLong("lastSyncMs"));
                d.instrument.runOnMainSync(()->{disabledEditors(d.activity.findViewById(android.R.id.content));for(String name:new String[]{"同步中…","移除同步设置","保存","取消"}){View button=d.find(d.activity.findViewById(android.R.id.content),name);assertNotNull(name,button);assertFalse(name,button.isEnabled());}});capture("automatic-running");progress("actual-timer-request-in-flight",baseline,began,fixture);
                JSONObject[] duplicate={null};d.instrument.runOnMainSync(()->duplicate[0]=RhActions.dispatch("sync.run",RhActions.obj()));assertFalse(duplicate[0].optBoolean("ok"));d.recreate();keepOwnedActivityAwake();assertTrue(d.state().getBoolean("syncBusy"));capture("recreated-while-running");fixture.release.countDown();fixture.gate=false;d.idle();assertEquals(2,fixture.puts.get());assertEquals(2,fixture.gets.get());assertEquals("completed",d.state().getJSONObject("sync").getString("phase"));assertTrue(d.state().getJSONObject("sync").getLong("lastSyncMs")>baseline);assertTrue(text().contains("上次完成："));assertFalse(text().contains("同步进行中"));capture("automatic-completed");
                automatic(false);d.click("保存");assertFalse(new RhSync(context).state().getBoolean("automatic"));long quiet=System.nanoTime()+TimeUnit.SECONDS.toNanos(35);while(System.nanoTime()<quiet){assertFalse(d.state().getBoolean("syncBusy"));assertEquals(2,fixture.puts.get());Thread.sleep(100);}capture("automatic-disabled");passed=true;RhShared.write(new File(output,"result.json"),RhActions.obj("passed",true,"intervalChoicesSaved",choices,"wallWaitMs",dueWall,"monotonicWaitMs",dueMonotonic,"actualFiveMinuteTimer",true,"timestampsModified",false,"manualSyncBeforeTimer",1,"automaticSyncCount",1,"pageReturned",true,"recreatedBeforeDue",true,"recreatedInFlight",true,"busyControlsDisabled",true,"duplicateRejected",true,"automaticDisabledAfterTest",true,"quietAfterDisableMs",35000,"realService",false,"systemInputInjected",false));
            }finally{fixture.gate=false;fixture.release.countDown();}
        }
    }
    @Test public void resetAfterFixtureCommitShowsReadableUncertaintyAndManualRetry()throws Exception{
        assertTrue("Owned emulator required",android.os.Build.HARDWARE.equals("ranchu")||android.os.Build.HARDWARE.equals("goldfish"));String run=InstrumentationRegistry.getArguments().getString("wireRun","");assertTrue(run.matches("wire-[a-z0-9-]{1,60}"));Context context=d.instrument.getTargetContext();output=new File(context.getExternalFilesDir("ui-evidence"),run);assertFalse(output.exists());assertTrue(output.mkdirs());
        try(Snapshot snapshot=new Snapshot(run);RhSyncFlowDeviceTest.Saved saved=d.new Saved();RhSyncFlowDeviceTest.Fixture fixture=new RhSyncFlowDeviceTest.Fixture()){
            String theme=InstrumentationRegistry.getArguments().getString("wireTheme","light");assertTrue(theme.equals("light")||theme.equals("dark"));RhShared.theme(context,theme.equals("dark"));saved.launch();d.configure(fixture);d.click("立即同步");d.idle();assertEquals("completed",d.state().getJSONObject("sync").getString("phase"));long previous=d.state().getJSONObject("sync").getLong("lastSyncMs");assertEquals(1,fixture.puts.get());
            fixture.resetNextPut=true;d.click("立即同步");d.idle();JSONObject uncertain=d.state().getJSONObject("sync");assertEquals(2,fixture.puts.get());assertTrue(uncertain.getBoolean("outcomeUncertain"));assertTrue(uncertain.getBoolean("automaticBlocked"));assertEquals(previous,uncertain.getLong("lastSyncMs"));assertEquals(RhShared.canonical(RhShared.read(context)),RhShared.canonical(new JSONObject(fixture.document)));assertTrue(text().contains("同步结果待确认"));String error=uncertain.getString("error");RhShared.write(new File(output,"uncertain.json"),RhActions.obj("error",error,"fixturePutCount",fixture.puts.get(),"automaticBlocked",true,"realService",false));capture("unconfirmed");assertTrue(error,error.startsWith("WebDAV 连接已中断")||error.startsWith("WebDAV 连接提前结束"));assertFalse(error.contains("Connection reset"));assertFalse(error.contains("unexpected end"));assertTrue(new RhSync(context).state().getBoolean("outcomeUncertain"));
            JSONObject[] auto={null};d.instrument.runOnMainSync(()->auto[0]=RhActions.dispatch("sync.run",RhActions.obj("automatic",true)));assertEquals("sync_interrupted",auto[0].getJSONObject("result").getString("reason"));assertEquals(2,fixture.puts.get());d.recreate();assertTrue(text().contains("同步结果待确认"));assertTrue(d.state().getJSONObject("sync").getBoolean("automaticBlocked"));capture("recreated-unconfirmed");
            d.click("立即同步");d.idle();JSONObject done=d.state().getJSONObject("sync");assertEquals("completed",done.getString("phase"));assertFalse(done.getBoolean("outcomeUncertain"));assertFalse(done.getBoolean("automaticBlocked"));assertFalse(new RhSync(context).state().getBoolean("outcomeUncertain"));assertEquals(3,fixture.puts.get());assertTrue(done.getLong("lastSyncMs")>previous);assertFalse(text().contains("同步结果待确认"));capture("retry-completed");passed=true;RhShared.write(new File(output,"result.json"),RhActions.obj("passed",true,"theme",theme,"actualTcpReset",true,"fixtureDocumentCommitted",true,"realService",false,"uiControls",true,"activityRecreated",true,"automaticCallBlocked",true,"manualRetrySucceeded",true,"fixturePutCount",3,"systemInputInjected",false,"processStopped",false));
        }
    }
}
